import{_ as s,a0 as r,w as i,s as l,ao as p,I as u,x as e,a1 as n,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"环境音播放器：让人放松的声音，保持你的创造力 | LCTT x X-CMD","titleTemplate":false,"description":"环境音播放器：让人放松的声音，保持你的创造力 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"环境音播放器：让人放松的声音，保持你的创造力 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"环境音播放器：让人放松的声音，保持你的创造力 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150407 Ambient Noise Player for Ubuntu Plays Relaxing Sounds to Keep You Creative","title":"环境音播放器：让人放松的声音，保持你的创造力","tag":"201505","desc":""},"relativePath":"201505/20150407 Ambient Noise Player for Ubuntu Plays Relaxing Sounds to Keep You Creative.md","filePath":"[post].md"}'),d={name:"201505/20150407 Ambient Noise Player for Ubuntu Plays Relaxing Sounds to Keep You Creative.md"};function m(b,t,f,g,T,x){const o=r("Link");return i(),l("div",null,[t[16]||(t[16]=p('<h1 id="环境音播放器-让人放松的声音-保持你的创造力" tabindex="-1">环境音播放器：让人放松的声音，保持你的创造力 <a class="header-anchor" href="#环境音播放器-让人放松的声音-保持你的创造力" aria-label="Permalink to “环境音播放器：让人放松的声音，保持你的创造力”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/04/raining-1600x900-wallpaper_www.wallpapermay.com_84-1.jpg" alt="Rain is a soothing sound for some"></p><p><em>对于某些人来说雨声是个令人安心的声音</em></p><p><strong>如果我想变得非常有效率，我不能听‘正常’的音乐。它会使我分心，我会开始跟着唱或者让我想起另一首歌，结局就是我在自己的音乐库里到处戳并且……反正，你懂的。</strong></p><p>同样我也不能在寂静的环境中工作（虽然和6只猫生活在一起意味着这不太可能）但是无规律的刺耳声音和突然地咔哒声以及猫叫声会打破寂静。</p><p>我的解决办法是听<strong>环境音</strong>。</p><p>我发现它能帮助我消除大脑的里的胡思乱想，提供了一个声景覆盖了猫咪玩耍的声音。</p><p>环境音就是日常生活中的背景噪音；雨滴在窗户上敲打的声音，咖啡店里人们聊天的嗡嗡声，风中鸟儿们闲聊的声音，等等。</p><p>倾听这些声音会强迫一个疯狂运行的大脑减速，重新沉静下来重新把精力聚集到重要的事情上。</p><h3 id="适用于ubuntu的环境音应用" tabindex="-1">适用于Ubuntu的环境音应用 <a class="header-anchor" href="#适用于ubuntu的环境音应用" aria-label="Permalink to “适用于Ubuntu的环境音应用”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/04/ambient-noise-player-750x365.jpg" alt=""></p><p>Google Play和苹果应用商店充满了环境音和白噪声的应用。现在，在Ubuntu里有同样的应用了。</p>',12)),u("p",null,[t[1]||(t[1]=e("‘",-1)),n(o,{href:"http://anoise.tuxfamily.org/"},{default:a(()=>[...t[0]||(t[0]=[e("Ambient Noise （环境音）",-1)])]),_:1}),t[2]||(t[2]=e(" ’——人如其名，这是一个专门被设计成播放这种声音的音频播放器。他甚至可以同Ubuntu声音菜单整合到一起，给你‘选择，点击即放松’的体验。",-1))]),t[17]||(t[17]=p(`<p>这个应用（又被称为‘ANoise播放器’，由Marcos Costales制作）带有<strong>8个高品质音频</strong>。</p><p>这8个预设音频涵盖了多种环境，从下雨时有节奏的声音，到夜晚大自然静谧的旋律，还有下午熙熙攘攘的咖啡店的嗡嗡声。</p><h3 id="在ubuntu上安装anoise播放器" tabindex="-1">在Ubuntu上安装ANoise播放器 <a class="header-anchor" href="#在ubuntu上安装anoise播放器" aria-label="Permalink to “在Ubuntu上安装ANoise播放器”">​</a></h3><p>适用于Ubuntu的环境音播放器是个免费的应用而且可以从它专用的PPA里安装。</p><p>要这样安装请先打开一个新的终端窗口运行:</p><pre><code>sudo add-apt-repository ppa:costales/anoise

sudo apt-get update &amp;&amp; sudo apt-get install anoise
</code></pre><p>安装好以后只需从Unity Dash（或桌面环境里类同的地方）里打开它，通过声音菜单选择你喜欢的环境音然后……放松吧！这个应用甚至记得你上次用的环境音。</p><p>即便如此，你还是要试一试看它是否能满足你的需要。我要说的是让我知道你是怎么想的，但是我将会专心致志到听不到你的声音——你可能也会这样！</p><hr>`,9)),u("p",null,[t[4]||(t[4]=e("via: ",-1)),n(o,{href:"http://www.omgubuntu.co.uk/2015/04/ambient-noise-player-app-for-ubuntu-linux"},{default:a(()=>[...t[3]||(t[3]=[e("http://www.omgubuntu.co.uk/2015/04/ambient-noise-player-app-for-ubuntu-linux",-1)])]),_:1})]),u("p",null,[t[8]||(t[8]=e("作者：",-1)),n(o,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:a(()=>[...t[5]||(t[5]=[e("Joey-Elijah Sneddon",-1)])]),_:1}),t[9]||(t[9]=e(" 译者：",-1)),n(o,{href:"https://github.com/H-mudcup"},{default:a(()=>[...t[6]||(t[6]=[e("H-mudcup",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:a(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),u("p",null,[t[13]||(t[13]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const P=s(d,[["render",m]]);export{_ as __pageData,P as default};
